'use strict';
let data,companies=[],view='map',selectedSector='Chips & memory';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={'Cloud & platforms':'#415a83','Chips & memory':'#637cf0','Chipmaking & design':'#856cce','Networking & servers':'#31a9a2','Power & grid':'#b29447','Energy supply':'#608d58','Cooling & construction':'#55a7c0','Data centers':'#b47758','Software & applications':'#668c87'};
const val=(c,k)=>c.metrics[k]?.value??null;
const sign=n=>n==null?'':n<0?'negative':'positive';
function money(n,cur='USD'){if(n==null)return '—';let a=Math.abs(n),u=a>=1e12?'T':a>=1e9?'B':a>=1e6?'M':'K',div=a>=1e12?1e12:a>=1e9?1e9:a>=1e6?1e6:1e3;return (n<0?'−':'')+(cur==='USD'?'$':cur==='EUR'?'€':cur==='KRW'?'₩':cur==='TWD'?'NT$':cur+' ')+(a/div).toLocaleString('en',{maximumFractionDigits:2})+u}
const pct=n=>n==null?'—':(n>0?'+':'')+n.toFixed(1)+'%';
const date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Unavailable';
function setView(v){if(view!==v)window.scrollTo({top:0});view=v;document.body.classList.toggle('universe-mode',v==='universe');window.MoneyUniverse?.setActive(v==='universe');$('.intro').hidden=v!=='map';$('#stats').hidden=['universe','scenarios','method','circulation','valuation','reports'].includes(v);for(const x of ['universe','map','money','method','recognition','scenarios','circulation','valuation','reports']){const e=$('#'+x+'-view');if(e)e.hidden=x!==v}$('#companies').hidden=!['map','money','recognition'].includes(v);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false')});if(companies.length)renderRows();if(v==='scenarios'&&scenariosData)renderScenarios();if(v==='circulation'&&circulationData)renderCirculation();if(v==='valuation'&&valuationData)renderValuation();}
function filterCompanies(){const q=$('#query').value.toLowerCase(),s=$('#sector').value,status=$('#status').value,basis=$('#basis').value;return companies.filter(c=>{let n=val(c,'net'),f=val(c,'fcf');return (view!=='recognition'||!$('#recognition-filter').value||recognition(c).key===$('#recognition-filter').value)&&(!q||(c.name+' '+c.ticker+' '+c.role).toLowerCase().includes(q))&&(!s||c.sector===s)&&(!basis||c.basis===basis)&&(!status||(status==='both'&&n>0&&f>0)||(status==='netloss'&&n!==null&&n<0)||(status==='cashburn'&&f!==null&&f<0)||(status==='mixed'&&n>0&&f!==null&&f<0)||(status==='missing'&&f===null))})}
function renderStats(){const profit=companies.filter(c=>val(c,'net')>0).length,loss=companies.filter(c=>val(c,'net')<0).length,fcf=companies.filter(c=>val(c,'fcf')>0).length,cashKnown=companies.filter(c=>val(c,'fcf')!==null).length;$('#stats').innerHTML=[['100','Public companies','9 layers of the global AI economy',''],[profit,'Reporting a profit',loss+' report a net loss','positive'],[fcf,'Generating free cash flow',cashKnown+' companies with cash-flow coverage','positive'],[companies.filter(c=>val(c,'fcf')!==null&&val(c,'fcf')<0).length,'Spending beyond cash flow','Company-wide figures · mixed periods','negative']].map(([num,title,note,cls])=>`<div class="stat"><span>${title}</span><strong class="${cls}">${num}</strong><small>${note}</small></div>`).join('')}
const positions={'Cloud & platforms':[12,165,186,110],'Chips & memory':[288,24,180,61],'Networking & servers':[288,107,180,61],'Power & grid':[288,190,180,61],'Cooling & construction':[288,273,180,61],'Data centers':[288,356,180,61],'Chipmaking & design':[555,24,183,61],'Energy supply':[555,190,183,61],'Software & applications':[555,356,183,61]};
function renderFlow(){let links=[['Cloud & platforms','Chips & memory'],['Cloud & platforms','Networking & servers'],['Cloud & platforms','Power & grid'],['Cloud & platforms','Cooling & construction'],['Cloud & platforms','Data centers'],['Chips & memory','Chipmaking & design'],['Power & grid','Energy supply'],['Data centers','Software & applications']];let svg='<svg viewBox="0 0 752 452" role="img" aria-label="Interactive schematic AI supply chain">';for(let [a,b] of links){let [x,y,w,h]=positions[a],[xx,yy,ww,hh]=positions[b],c=colors[b];let sy=y+h/2;if(a==='Cloud & platforms')sy=y+16+links.filter(l=>l[0]===a).findIndex(l=>l[1]===b)*19;svg+=`<path class="flow-line ${selectedSector===a||selectedSector===b?'focus':''}" stroke="${c}" stroke-width="${a==='Cloud & platforms'?19:15}" d="M${x+w} ${sy} C${x+w+45} ${sy},${xx-45} ${yy+hh/2},${xx} ${yy+hh/2}"/>`}for(let [s,[x,y,w,h]] of Object.entries(positions)){let count=companies.filter(c=>c.sector===s).length,sel=s===selectedSector;svg+=`<g class="node" role="button" tabindex="0" data-sector="${esc(s)}" aria-label="Explore ${esc(s)}, ${count} companies" aria-pressed="${sel}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${sel?'#102135':'white'}" stroke="${sel?'#102135':'#d4dce6'}"/><rect x="${x}" y="${y+10}" width="3" height="${h-20}" rx="1" fill="${colors[s]}"/><text x="${x+13}" y="${y+25}" class="sector-node-title" fill="${sel?'white':'#102135'}">${esc(s)}</text><text x="${x+13}" y="${y+45}" class="sector-node-sub" style="fill:${sel?'#c1cedf':'#697588'}">${count} public companies</text>${s==='Cloud & platforms'?`<text x="${x+13}" y="${y+77}" class="sector-node-sub">Build, buy & monetize AI</text><text x="${x+13}" y="${y+94}" class="sector-node-sub">MSFT · AMZN · GOOGL · META</text>`:''}</g>`}$('#flow').innerHTML=svg+'</svg>';$('#flow').querySelectorAll('[data-sector]').forEach(e=>{const act=()=>{selectedSector=e.dataset.sector;renderFlow();renderSector()};e.addEventListener('click',act);e.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();act()}})})}
function renderSector(){const list=companies.filter(c=>c.sector===selectedSector),positive=list.filter(c=>val(c,'net')>0).length;$('#sector-detail').innerHTML=`<span class="eyebrow">EXPLORE A LAYER</span><h3>${esc(selectedSector)}</h3><p>${list.length} companies · ${positive} reporting a profit.<br>Explore their role and reported financials.</p>`+list.slice(0,5).map(c=>`<button class="sector-company" data-company="${esc(c.ticker)}"><span class="ticker-block">${esc(c.ticker.split('.')[0])}</span><span><b>${esc(c.name)}</b><small>Net <span class="${sign(val(c,'net'))}">${money(val(c,'net'),c.currency)}</span> · ${c.basis}</small></span></button>`).join('')+`<button class="sector-full" id="view-sector">View all ${list.length} companies</button>`;bindCompanies($('#sector-detail'));$('#view-sector').onclick=()=>{$('#sector').value=selectedSector;renderRows();$('#companies').scrollIntoView({behavior:'smooth',block:'start'})}}
function renderRows(){let list=filterCompanies(),sort=$('#sort').value;if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));else{const k=sort.replace('-asc',''),dir=sort.endsWith('-asc')?1:-1;list.sort((a,b)=>a[k]==null?1:b[k]==null?-1:dir*(a[k]-b[k]))}if(view==='recognition'){renderMarketRows(list);renderRecognition();return}$('#companies thead').innerHTML='<tr><th>Company / role</th><th>Period ending</th><th>Revenue</th><th>Net profit / loss</th><th>Free cash flow</th><th>Net / cash margin</th></tr>';$('#count').textContent=`${list.length} of ${companies.length} companies · figures in reported currency`;$('#rows').innerHTML=list.map(c=>`<tr><td><button class="name-button" data-company="${esc(c.ticker)}">${esc(c.name)}</button><span class="company-ticker">${esc(c.ticker)}</span><small class="role" title="${esc(c.role)}">${esc(c.role)}</small></td><td><span class="badge">${esc(c.basis)}</span>${date(c.end)}<small class="${c.stale?'old':''}">${c.stale?'Older reporting period':esc(c.currency||'Not verified')}</small></td><td>${money(val(c,'revenue'),c.currency)}</td><td class="${sign(val(c,'net'))}">${money(val(c,'net'),c.currency)}<small>${val(c,'net')==null?'Not verified':val(c,'net')<0?'Net loss':'Net profit'}</small></td><td class="${sign(val(c,'fcf'))}">${money(val(c,'fcf'),c.currency)}<small>${val(c,'fcf')==null?'Unavailable':c.fcfReported?'Company definition':'OCF − cash capex'}</small></td><td><span class="${sign(c.margin)}">${pct(c.margin)}</span><small class="${sign(c.fcfMargin)}">${pct(c.fcfMargin)} FCF</small></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No companies match these filters. Try a different layer or reset the filters.</td></tr>';bindCompanies($('#rows'));if(view==='money')renderScatter();if(view==='recognition'&&typeof renderRecognition==='function')renderRecognition()}
function bindCompanies(root){root.querySelectorAll('[data-company]').forEach(b=>b.addEventListener('click',()=>openCompany(b.dataset.company)))}
function renderScatter(){let list=filterCompanies().filter(c=>c.margin!==null&&c.fcfMargin!==null);const clamp=n=>Math.min(65,Math.max(-45,n)),x=n=>100+(clamp(n)+45)/110*780,y=n=>350-(clamp(n)+45)/110*290,x0=x(0),y0=y(0);let svg=`<svg viewBox="0 0 960 415" role="img" aria-label="Net income margin versus free cash flow margin"><rect x="${x0}" y="60" width="${880-x0}" height="${y0-60}" fill="#eff8f3"/><rect x="100" y="${y0}" width="${x0-100}" height="${350-y0}" fill="#fff1f0"/><text x="114" y="46" fill="#657182" font-size="12">CASH MARGIN</text><text x="900" y="397" text-anchor="end" fill="#657182" font-size="12">NET PROFIT MARGIN</text><text x="${x0+15}" y="78" fill="#388467" font-size="12">Profit + cash generation</text><text x="114" y="336" fill="#b35f66" font-size="12">Loss + negative FCF</text>`;for(let n of [-40,-20,0,20,40,60]){svg+=`<path d="M100 ${y(n)}H880 M${x(n)} 60V350" stroke="${n===0?'#9daaba':'#e4e9ee'}" stroke-dasharray="${n===0?'0':'3 4'}"/><text x="90" y="${y(n)+4}" font-size="11" text-anchor="end" fill="#718092">${n}%</text><text x="${x(n)}" y="371" font-size="11" text-anchor="middle" fill="#718092">${n}%</text>`}for(let c of list){const out=c.margin>65||c.margin< -45||c.fcfMargin>65||c.fcfMargin< -45;svg+=`<circle class="plot-point" tabindex="0" role="button" aria-label="${esc(c.name)}, net margin ${pct(c.margin)}, cash margin ${pct(c.fcfMargin)}" data-company="${esc(c.ticker)}" cx="${x(c.margin)}" cy="${y(c.fcfMargin)}" r="${out?6:5}" fill="${colors[c.sector]}"><title>${esc(c.name)} (${c.ticker}) — net ${pct(c.margin)}, FCF ${pct(c.fcfMargin)}${out?' · outside chart range':''}</title></circle>`}$('#scatter').innerHTML=svg+`<text x="100" y="397" font-size="11" fill="#657182">${list.length} companies with both metrics</text></svg>`;bindCompanies($('#scatter'));$('#scatter').querySelectorAll('[data-company]').forEach(e=>e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();openCompany(e.dataset.company)}})}
function openCompany(ticker){const c=companies.find(c=>c.ticker===ticker);if(!c)throw Error('Unknown company');const n=val(c,'net'),f=val(c,'fcf'),picture=n===null?'Financial data incomplete':n>=0?(f===null?'Profitable; cash coverage incomplete':f>=0?'Profitable and generating free cash flow':'Profitable, but free cash flow is negative'):(f===null?'Reporting a net loss; cash coverage incomplete':f>=0?'Reporting a loss, with positive free cash flow':'Reporting a loss and negative free cash flow');$('#company-content').innerHTML=`<span class="eyebrow">${esc(c.sector)} / ${esc(c.ticker)}</span><h2 id="company-title">${esc(c.name)}</h2><button class="export-button company-export" data-ticker="${esc(c.ticker)}">Create company PDF ↗</button><div id="company-pdf-status" class="pdf-ready" role="status" hidden></div><p>${esc(c.role)}</p><p class="note">${picture}</p><p class="mini-label"><b>${c.basis}</b> · ${date(c.start)} – ${date(c.end)} · ${esc(c.currency||'')}<br>${c.stale?'Older reporting period. Check linked issuer results for more recent releases.':''}</p><div class="detail-metrics">${[['revenue','Revenue'],['net','Net profit / loss'],['ocf','Operating cash flow'],['capex','Cash capital expenditure'],['fcf','Free cash flow'],['operating','Operating profit']].map(([k,label])=>`<div class="detail-metric"><span>${label}</span><b class="${['net','fcf','operating'].includes(k)?sign(val(c,k)):''}">${money(val(c,k),c.currency)}</b><small>${k==='fcf'&&c.fcfReported?'Company-reported definition':val(c,k)==null?'Not available for this period':esc(c.basis)}</small></div>`).join('')}</div><p>Net margin <b>${pct(c.margin)}</b> · Free cash flow margin <b>${pct(c.fcfMargin)}</b></p>${c.latestQuarter?`<h3>Latest quarter in the source data</h3><p>Ended ${date(c.latestQuarter.end)} · net income <b class="${sign(c.latestQuarter.net)}">${money(c.latestQuarter.net,c.currency)}</b>${c.latestQuarter.revenue!=null?' · revenue '+money(c.latestQuarter.revenue,c.currency):''}. This quarter may differ from the trailing-period picture above.</p>`:''}${valuationDetail(c)}${companyCirculation(c)}${scenarioDetail(c)}${c.market?marketDetail(c):''}${c.history?.length?`<h3>Annual financial context</h3><div class="table-wrap"><table class="history"><thead><tr><th>Fiscal year ending</th><th>Revenue</th><th>Net income</th></tr></thead><tbody>${c.history.map(h=>`<tr><td>${date(h.end)}</td><td>${money(h.metrics.revenue?.value,c.currency)}</td><td class="${sign(h.metrics.net?.value)}">${money(h.metrics.net?.value,c.currency)}</td></tr>`).join('')}</tbody></table></div>`:''}<h3>Cash-flow definition</h3><p>${esc(c.fcfDefinition||'Cash-flow components have not yet been verified for this period; unavailable values are not treated as zero.')}</p>${c.dataNote?`<p class="note">${esc(c.dataNote)}</p>`:''}<h3>Financial sources</h3><div class="sources">${c.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a>`).join('')}</div><details><summary>Calculation provenance</summary><p>TTM = latest fiscal year + current YTD − prior YTD. Exact inputs are listed below.</p>${Object.entries(c.metrics).map(([key,m])=>`<h3>${esc(key.toUpperCase())} · ${esc(m.method)}</h3>${m.components?.length?`<table class="source-table"><thead><tr><th>Period</th><th>Amount</th><th>Filed</th></tr></thead><tbody>${m.components.map(z=>`<tr><td>${esc(z.start)} to ${esc(z.end)}<small>${esc(z.tag)}</small></td><td>${money(z.val,z.currency)}</td><td>${esc(z.filed)}</td></tr>`).join('')}</tbody></table>`:'<p>Transcribed from the linked company release.</p>'}`).join('')}</details>`;$('#company-content .company-export').onclick=()=>downloadResearchReport('company',ticker);if(!$('#company-dialog').open)$('#company-dialog').showModal();$('#company-dialog').scrollTop=0}
function recognition(c){
 if(!c.market||c.revenueGrowth==null||val(c,'net')===null||val(c,'fcf')===null||c.stale)return {key:'incomplete',label:'Insufficient fresh evidence',color:'#8a929e'};
 const strong=c.revenueGrowth>=10&&val(c,'net')>0&&val(c,'fcf')>0;
 if(strong&&c.market.excess<0){
  if(c.market.boomComparable&&c.market.boomExcess<0)return {key:'candidate',label:'Potential hidden champion',color:'#087454'};
  return {key:'recent',label:c.market.boomComparable?'Recent laggard; prior boom gains':'Recent laggard; limited 2023 history',color:'#96633a'};
 }
 if(strong&&c.market.excess>=0&&c.market.return1y>0)return {key:'recognized',label:'Strong business, strong stock',color:'#315cec'};
 return {key:'watch',label:'Other / mixed evidence',color:'#8c7038'};
}
function marketDetail(c){const m=c.market,r=recognition(c),h=m.history,min=Math.min(0,...h.map(p=>Math.min(p.stock,p.benchmark))),max=Math.max(1,...h.map(p=>Math.max(p.stock,p.benchmark))),y=v=>135-(v-min)/(max-min)*110,x=i=>20+i/(h.length-1)*450,path=k=>h.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(p[k]).toFixed(1)).join(' ');return `<h3>Has the market recognized it?</h3><p class="note" style="color:${r.color}"><b>${r.label}</b></p><div class="detail-metrics"><div class="detail-metric"><span>One-year stock return</span><b class="${sign(m.return1y)}">${pct(m.return1y)}</b></div><div class="detail-metric"><span>Versus ${esc(m.benchmark)}</span><b class="${sign(m.excess)}">${m.excess>0?'+':''}${m.excess.toFixed(1)} pp</b></div></div><div class="boom-context"><b>${m.boomComparable?'Since the start of 2023':'Longer history · comparability limited'}</b><p>Stock ${pct(m.boomReturn??null)} · ${esc(m.benchmark)} ${pct(m.boomBenchmarkReturn??null)}<br>Relative return: ${m.boomExcess!=null?(m.boomExcess>0?'+':'')+m.boomExcess.toFixed(1)+' pp':'—'} · from ${date(m.boomStart)}</p><p class="mini-label">${esc(m.boomNote||'Longer history not available.')}</p></div><svg viewBox="0 0 490 170" role="img" aria-label="One-year cumulative stock and benchmark price returns"><line x1="20" x2="470" y1="${y(0)}" y2="${y(0)}" stroke="#dbe1e7"/><path d="${path('benchmark')}" fill="none" stroke="#98a4b2" stroke-width="2"/><path d="${path('stock')}" fill="none" stroke="#315cec" stroke-width="2.5"/><text x="20" y="163" font-size="11" fill="#657182">${esc(m.start)}</text><text x="470" y="163" text-anchor="end" font-size="11" fill="#657182">${esc(m.end)}</text></svg><p class="mini-label"><span style="color:#315cec">━ ${esc(c.ticker)}</span> &nbsp; <span style="color:#758496">━ ${esc(m.benchmark)} ${pct(m.benchmarkReturn)}</span></p><p>Reported revenue growth: <b>${pct(c.revenueGrowth)}</b> year on year (${c.basis}, ending ${date(c.end)}).<br>Last close: ${Number(m.close).toLocaleString('en',{maximumFractionDigits:2})} ${m.currency} on ${date(m.end)}.</p><p class="mini-label">${esc(m.definition)}</p><div class="sources"><a href="${esc(m.source)}" target="_blank" rel="noopener">Stock-price history — Yahoo Finance</a><a href="${esc(m.benchmarkSource)}" target="_blank" rel="noopener">${esc(m.benchmark)} price history</a></div>`}
function renderMarketRows(list){$('#count').textContent=`${list.length} of ${companies.length} companies · one-year price performance`;$('#companies thead').innerHTML='<tr><th>Company / role</th><th>Stock return · 1 year</th><th>Relative to benchmark</th><th>Since 2023 · stock / relative</th><th>Revenue growth · YoY</th><th>Profit / FCF</th><th>Recognition screen</th></tr>';$('#rows').innerHTML=list.map(c=>{const m=c.market,r=recognition(c);return `<tr><td><button class="name-button" data-company="${esc(c.ticker)}">${esc(c.name)}</button><span class="company-ticker">${esc(c.ticker)}</span><small class="role">${esc(c.role)}</small></td><td class="${sign(m?.return1y)}">${pct(m?.return1y??null)}<small>To ${date(m?.end)}</small></td><td class="${sign(m?.excess)}">${m?(m.excess>0?'+':'')+m.excess.toFixed(1)+' pp':'—'}<small>${esc(m?.benchmark||'Unavailable')}</small></td><td>${pct(m?.boomReturn??null)}<small>${m?.boomComparable?(m.boomExcess>0?'+':'')+m.boomExcess.toFixed(1)+' pp vs index':'Limited comparability'}</small></td><td>${pct(c.revenueGrowth)}<small>${c.basis} · ${date(c.end)}</small></td><td><span class="${sign(val(c,'net'))}">${val(c,'net')===null?'Unknown':val(c,'net')>0?'Profit':'Loss'}</span><small class="${sign(val(c,'fcf'))}">${val(c,'fcf')===null?'FCF unavailable':val(c,'fcf')>0?'Positive FCF':'Negative FCF'}</small></td><td><span class="screen-tag" style="color:${r.color}">${r.label}</span></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No companies match this screen. Reset the filters to see the full universe.</td></tr>';bindCompanies($('#rows'))}
function renderRecognition(){const list=filterCompanies();$('#recognition-stats').innerHTML=[['candidate','Potential hidden champions'],['recognized','Strong business + strong stock'],['recent','Recent laggard / prior boom'],['watch','Other / mixed evidence'],['incomplete','Insufficient fresh evidence']].map(([key,label])=>`<div><b>${list.filter(c=>recognition(c).key===key).length}</b><span>${label}</span></div>`).join('');const candidates=list.filter(c=>recognition(c).key==='candidate').sort((a,b)=>a.market.excess-b.market.excess).slice(0,4);$('#candidate-cards').innerHTML=candidates.length?candidates.map(c=>`<button class="candidate" data-company="${esc(c.ticker)}"><span class="eyebrow">${esc(c.sector)}</span><h3>${esc(c.name)}</h3><span class="candidate-ticker">${esc(c.ticker)} · potential hidden champion</span><div><span>Revenue growth <b>${pct(c.revenueGrowth)}</b></span><span>1-year stock vs index <b class="negative">${c.market.excess.toFixed(1)} pp</b></span><span>Since 2023 vs index <b class="negative">${c.market.boomExcess.toFixed(1)} pp</b></span></div><p>Positive profit + free cash flow<br>${c.basis} through ${date(c.end)}</p></button>`).join(''):'<p class="small">No potential hidden champions match the current filters. Broaden the filters to explore other companies.</p>';bindCompanies($('#candidate-cards'))}
$('#recognition-filter').addEventListener('change',renderRows);
$('#close-dialog').onclick=()=>$('#company-dialog').close();$('#company-dialog').addEventListener('click',e=>{if(e.target===$('#company-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)e.target.close()}});
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('.brand').onclick=e=>{e.preventDefault();setView('universe')};for(let id of ['query','sector','status','basis','sort'])$('#'+id).addEventListener(id==='query'?'input':'change',renderRows);$('#reset').onclick=()=>{['query','sector','status','basis'].forEach(id=>$('#'+id).value='');$('#sort').value='name';$('#recognition-filter').value='';renderRows()};
Promise.all(['data.json','scenarios.json','valuation.json','circulation.json'].map(url=>fetch(url,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}))).then(([d,s,v,f])=>{data=d;companies=d.companies;scenariosData=s;valuationData=v;circulationData=f;$('#loading').hidden=true;for(const sector of Object.keys(colors))$('#sector').insertAdjacentHTML('beforeend',`<option>${esc(sector)}</option>`);renderStats();renderFlow();renderSector();initScenarios();$('#scenario-sources').innerHTML=Object.entries(s.sources).map(([id,x])=>`<article>${sourceLink(id)}<p>${esc(x.note)}</p></article>`).join('');initExpansion();MoneyUniverse.init();setView('universe');registerTools()}).catch(e=>{$('#loading').textContent='Research data could not be loaded. Reload the page to try again.';console.error(e)});
function registerTools(){if(!document.modelContext?.registerTool)return;const life=new AbortController();for(const tool of [{name:'inspect_money_link',description:'Show source evidence for one circulation relationship. Changes only the visible view.',inputSchema:{type:'object',properties:{linkId:{type:'string'}},required:['linkId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({linkId})=>{const edge=circulationData.edges.find(e=>e.id===linkId);if(!edge)throw Error('Unknown relationship ID');circulationTier='all';selectedCaseId=circulationData.cases.find(c=>c.edgeIds.includes(linkId))?.id||'';setView('circulation');selectedEdgeId=linkId;renderEdgeDetail(linkId);return {...edge,sources:edge.sourceIds.map(id=>circulationData.sources[id])}}},{name:'filter_valuation',description:'Show valuation/debt records matching a company search. Prices and share counts are dated, not live.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({query})=>{if(typeof query!=='string'||query.length>200)throw Error('Invalid company search');$('#valuation-query').value=query;$('#valuation-focus').value='all';setView('valuation');return {count:valuationFiltered().length,companies:valuationFiltered().map(c=>({ticker:c.ticker,...valuationRecord(c)}))}}},{name:'explore_ai_scenario',description:'Show one of the three 2030 scenarios and return its conditional hidden-champion candidates. Changes only local view filters.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['buildout','diffusion','reset']},window:{type:'string',enum:['both','recent']}},required:['scenario','window'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({scenario,window:stockWindow})=>{const idx=['buildout','diffusion','reset'].indexOf(scenario);if(idx<0||!['both','recent'].includes(stockWindow))throw Error('Unknown scenario or recognition window');scenarioIndex=idx;recognitionWindow=stockWindow;recognitionGap=0;scenarioFocus='hidden';scenarioQuery='';scenarioSector='';$('#scenario-query').value='';$('#scenario-sector').value='';$('#scenario-focus').value='hidden';$('#scenario-gap').value='0';$('#scenario-window').value=stockWindow;setView('scenarios');return {scenario:currentScenario().name,window:stockWindow,candidates:companies.filter(c=>hiddenInScenario(c)).map(c=>({ticker:c.ticker,name:c.name,rating:scenarioRating(c),period:c.end,stockExcess1y:c.market.excess,stockExcessSince2023:c.market.boomExcess})),caveat:'Conditional business positioning and benchmark lag; not a fair-value estimate or stock-return prediction.'}}},{name:'inspect_ai_company',description:'Open company financials and return its dated metrics and source links.',inputSchema:{type:'object',properties:{ticker:{type:'string'}},required:['ticker'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({ticker})=>{if(typeof ticker!=='string'||!companies.some(c=>c.ticker===ticker))throw Error('Unknown ticker');openCompany(ticker);const c=companies.find(c=>c.ticker===ticker);return {ticker:c.ticker,period:c.end,basis:c.basis,metrics:c.metrics,sources:c.sources}}},{name:'filter_ai_companies',description:'Show all companies in a supply-chain layer, clearing other company filters.',inputSchema:{type:'object',properties:{sector:{type:'string',enum:['',...Object.keys(colors)]}},required:['sector'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({sector})=>{if(typeof sector!=='string'||(sector&&!colors[sector]))throw Error('Unknown sector');['query','status','basis','recognition-filter'].forEach(id=>$('#'+id).value='');$('#sector').value=sector;setView('map');renderRows();return {count:filterCompanies().length,sector}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
